// n8n Code node: "Match Catalog"  (Mode: Run Once for All Items, Language: JavaScript)
// Input : items from "Get row(s) in sheet" (sku, name, active_ingredient, strength, form,
//         price_egp, stock, reorder_level, controlled)
// Reads : "AI Read Request" (Gemini) and "Prepare Prescription Read" / "Prepare Text Read"
// Output feeds the Switch: nothing -> "Nothing found", needsPharmacist -> "Pharmacist", else -> "Auto reserve"

const req = $('AI Read Request').first().json;
const src = ($('Prepare Prescription Read').isExecuted
  ? $('Prepare Prescription Read')
  : $('Prepare Text Read')).first().json;

// ---------- 1) Read the medicines from Gemini ----------
let r = null;
let raw = '';
try {
  const parts = req.candidates?.[0]?.content?.parts || [];
  // ignore Gemini "thinking" parts, keep only the answer text
  raw = parts.filter(p => !p.thought).map(p => p.text || '').join('');
  const s = raw.indexOf('{'), e = raw.lastIndexOf('}');   // tolerate ```json fences / extra text
  if (s !== -1 && e > s) r = JSON.parse(raw.slice(s, e + 1));
} catch (err) {
  r = null;
}

// ---------- 2) Fallback for plain text messages (e.g. "panadol", "panadol 2, brufen") ----------
if ((!r || !Array.isArray(r.medicines)) && src.type === 'text' && String(src.text || '').trim()) {
  const medicines = String(src.text)
    .split(/[\n,،;+]|\s+and\s+|\s+و\s+/i)
    .map(t => t.trim())
    .filter(Boolean)
    .map(t => {
      const m = t.match(/^(.*?)\s*(?:x\s*)?(\d{1,2})$/i);     // "panadol 2" / "panadol x2"
      return m && m[1] ? { name: m[1].trim(), qty: Number(m[2]) } : { name: t, qty: 1 };
    });
  r = { readable: medicines.length > 0, medicines };
}
if (!r) r = { readable: false, medicines: [] };

// ---------- 3) Catalog helpers ----------
const cat = $input.all().map(i => i.json).filter(p => p.sku);

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]/g, '');
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

const lev = (a, b) => {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      d[i][j] = Math.min(
        d[i - 1][j] + 1,
        d[i][j - 1] + 1,
        d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
  return d[a.length][b.length];
};

// cheapest in-stock product with same active ingredient + strength
const findAlternative = (p, qty) => {
  const alts = cat
    .filter(x =>
      x.sku !== p.sku &&
      norm(x.active_ingredient) === norm(p.active_ingredient) &&
      norm(x.strength) === norm(p.strength) &&
      num(x.stock) >= qty)
    .sort((a, b) => num(a.price_egp) - num(b.price_egp));
  return alts.length ? `${alts[0].name} ${alts[0].strength} (${alts[0].sku})` : '';
};

// ---------- 4) Match every requested medicine against the sheet ----------
const lines = [], unclear = [];

for (const item of (r.medicines || []).slice(0, 10)) {
  const m = typeof item === 'string' ? { name: item } : item;
  const n = norm(m.name);
  if (!n || n === '?') { unclear.push(m.name || '?'); continue; }

  // closest row by brand name OR active ingredient
  const best = cat
    .map(p => ({ p, d: Math.min(lev(n, norm(p.name)), lev(n, norm(p.active_ingredient))) }))
    .sort((a, b) => a.d - b.d)[0];

  if (!best || best.d > Math.max(2, n.length * 0.3)) { unclear.push(m.name); continue; }

  const p = best.p;
  const qty = Math.max(1, Math.min(5, Math.round(Number(m.qty) || 1)));
  const inStock = num(p.stock) >= qty;

  lines.push({
    sku: p.sku,
    name: `${p.name} ${p.strength}`,
    qty,
    price: num(p.price_egp),
    stock: num(p.stock),          // current stock of the matched medicine
    in_stock: inStock,
    controlled: String(p.controlled).trim().toLowerCase() === 'yes',
    fuzzy: best.d > 0,
    alternative: inStock ? '' : findAlternative(p, qty),
  });
}

const total = lines.filter(l => l.in_stock).reduce((s, l) => s + l.price * l.qty, 0);

// ---------- 5) Output ----------
return [{
  json: {
    customer_id: src.customer_id,
    customer_name: src.customer_name,
    wa_phone_id: src.wa_phone_id,
    type: src.type,
    text: src.text,
    media_id: src.media_id || '',
    ...(src.mime ? { mime: src.mime } : {}),
    group: src.group,
    lines,
    unclear,
    readable: r.readable !== false,
    needsPharmacist:
      lines.some(l => l.controlled || l.fuzzy) || unclear.length > 0 || r.readable === false,
    nothing: lines.length === 0,
    total,
    // debug: shows what Gemini returned; delete this line once everything works
    ai_raw: raw.slice(0, 300),
  },
}];

return [
  {
    json: {
      ...$json,
      prompt: `A customer wrote to an Egyptian pharmacy.

Return JSON only:
{
  "is_prescription": false,
  "readable": true,
  "medicines": [
    {
      "name": "",
      "strength": "",
      "qty": 1
    }
  ],
  "other": "greeting|question|empty"
}

Rules:
- Only include medicines the customer explicitly asks for.
- Do not invent medicine names or strengths.
- If the message is unreadable, set "readable" to false.
- If no medicine is requested, return an empty medicines array.
- Return valid JSON only, without Markdown.

Message: <<<${$json.text || ""}>>>`
    }
  }
];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');

const input = $('Normalization Message').first().json;

const mime = $input.first().binary?.data?.mimeType || 'image/jpeg';

return [
  {
    json: {
      ...input,
      b64: buf.toString('base64'),
      mime,

      prompt: `This is a photo of an Egyptian prescription or medicine box.

Return JSON only:
{
  "is_prescription": true,
  "readable": true,
  "medicines": [
    {
      "name": "",
      "strength": "",
      "qty": 1
    }
  ]
}

Rules:
- Identify medicines visible in the image.
- Only include medicines requested by the customer.
- qty = number of boxes requested; default to 1.
- Never guess an unreadable name. Use "unreadable".
- Never invent medicine strengths.
- If the image is unclear, set readable to false.
- If no medicines are identified, return an empty medicines array.
- Return valid JSON only, without Markdown.`
    }
  }
];

// n8n Code node: "One Row per Medicine"  (Mode: Run Once for All Items, Language: JavaScript)
// Input : 1 item from "Match Catalog"
// Output: one item per medicine (plus one per unclear name), ready to append to the Reservations sheet

const j = $input.first().json;

// Hold time for a reservation (hours). Change to match your pharmacy policy.
const HOLD_HOURS = 2;

// Pharmacist review -> not reserved automatically
const status = j.needsPharmacist ? 'pending_pharmacist' : 'reserved';
const exp = $now.plus({ hours: HOLD_HOURS }).toFormat('yyyy-MM-dd HH:mm');

const base = {
  customer_id: j.customer_id,
  wa_phone_id: j.wa_phone_id,
  customer_name: j.customer_name,
};

// One row per matched medicine
const rows = (j.lines || []).map(l => ({
  ...base,
  sku: l.sku,
  name: l.name,
  qty: l.qty,
  total_egp: l.qty * l.price,
  status,
  expires_at: status === 'reserved' ? exp : '',
  note: [
    l.controlled ? 'controlled' : '',
    l.in_stock ? '' : 'out of stock',
    l.alternative ? 'alt: ' + l.alternative : '',
    l.fuzzy ? 'fuzzy match' : '',
  ].filter(Boolean).join('; '),
}));

// One row per name that could not be matched / read
for (const u of (j.unclear || [])) {
  rows.push({
    ...base,
    sku: '',
    name: String(u),
    qty: 1,
    total_egp: 0,
    status: 'pending_pharmacist',
    expires_at: '',
    note: 'not in catalog or unreadable',
  });
}

// res_id = group + running number, e.g. R-261116-P1B6-1
// one reservation ID shared by every row of this request
const group = j.group || ('R-' + $now.toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase());

return rows.map((r, k) => ({ json: { res_id: group + '-' + (k + 1), ...r } }));

// n8n Code node: "Take Stock Now"  (Mode: Run Once for All Items, Language: JavaScript)
// Stock leaves the shelf only when a line is reserved, and never goes below zero.

// Current stock per SKU, from the catalog sheet node ("Get row(s) in sheet", 10 items)
const cat = Object.fromEntries(
  $('Read Catalog').all()
    .map(i => i.json)
    .filter(p => p.sku)
    .map(p => [p.sku, Number(p.stock)])
);

const lines = $('Match Catalog').first().json.lines;

// Subtract each reserved quantity; stop with an error if stock is unknown or would go negative
for (const l of lines) {
  if (!Number.isFinite(cat[l.sku])) throw new Error('VALIDATION: SKU ' + l.sku + ' not found in catalog');
  cat[l.sku] -= l.qty;
  if (cat[l.sku] < 0) throw new Error('VALIDATION: stock for ' + l.sku + ' would go negative');
}

// One item per line with the new stock level (used to update the catalog sheet)
return lines.map(l => ({ json: { sku: l.sku, stock: cat[l.sku] } }));

const m = $json.messages?.[0];

if (!m) return [];

return [
  {
    json: {
      customer_id: m.from || "",
      customer_name: $json.contacts?.[0]?.profile?.name || "",
      wa_phone_id: $json.metadata?.phone_number_id || "",
      type: m.type || "",
      text: m.text?.body || m.image?.caption || "",
      media_id: m.image?.id || ""
    }
  }
];

const q = $json.callback_query;

if (!q) return [];

const [, action, group, customer] = String(q.data || '').split(':');

if (!group) return [];

return [
  {
    json: {
      action,
      group,
      customer,
      query_id: q.id,
      chat_id: q.message?.chat?.id,
      message_id: q.message?.message_id,
      original: q.message?.text || '',
      by: q.from?.username || q.from?.first_name || ''
    }
  }
];

// n8n Code node: "Apply Decision"  (Mode: Run Once for All Items, Language: JavaScript)
// Input : items from "Read Catalog (Decision)" (catalog rows: sku, name, ..., stock, ...)
// Runs after the pharmacist taps Approve / Reject in Telegram.
// NOTE: this node does NOT change the stock numbers. It only reads and shows them.

// 1) Decision data from the Telegram callback (action, group, customer, query_id, chat_id,
//    message_id, original, by)
const d = $('Parse Decision').first().json;

// 2) Reservation rows of this request that are still waiting for the pharmacist
//    (they come from "Find Pending Lines", NOT from the catalog).
//    Accepts a group like "R-261122-P8W2" or a full row id like "R-261122-P8W2-1".
const seen = new Set();
const lines = $('Find Pending Lines').all()
  .map(i => i.json)
  .filter(r => {
    const id = String(r.res_id || '');
    const match = id === d.group || id.startsWith(d.group + '-') || d.group.startsWith(id + '-');
    if (!match || r.status !== 'pending_pharmacist' || seen.has(id)) return false;
    seen.add(id);                       // ignore duplicate rows
    return true;
  });

// Nothing waiting => somebody already decided (or the request does not exist)
if (!lines.length) return [{ json: { ...d, ok: false, toast: 'Already decided or not found' } }];

// 3) Current stock per SKU from the catalog (read only, never modified)
const stock = Object.fromEntries($input.all().map(i => [i.json.sku, Number(i.json.stock)]));

// On approve: only CHECK that there is enough stock (nothing is subtracted)
if (d.action === 'approve') {
  for (const l of lines) {
    if (stock[l.sku] < Number(l.qty)) {
      return [{ json: { ...d, ok: false, toast: 'Not enough stock for ' + l.name + '. Edit the request or reject.' } }];
    }
  }
}

// Reservation hold: 2 hours from now (Cairo time)
const exp = $now.setZone('Africa/Cairo').plus({ hours: 2 }).toFormat('yyyy-MM-dd HH:mm');

const skus = [...new Set(lines.map(l => l.sku).filter(Boolean))];

return [{
  json: {
    ...d,
    ok: true,
    toast: d.action === 'approve' ? 'Approved' : 'Rejected',
    // every line also shows the current stock of its medicine (unchanged)
    lines: lines.map(l => ({ ...l, stock: stock[l.sku] })),
    // current stock level for every SKU in the request (unchanged)
    newStock: skus.map(s => ({ sku: s, stock: stock[s] })),
    // ready-made text, e.g. "Panadol 500 mg: 31"
    stock_text: lines
      .filter(l => l.sku)
      .map(l => `${l.name}: ${stock[l.sku]}`)
      .join('\n'),
    exp,
    wa_phone_id: lines[0].wa_phone_id,
    total: lines.reduce((s, l) => s + Number(l.total_egp), 0),
  },
}];

const d = $('Apply Decision').first().json;

// 1) lines from Apply Decision; if empty, look them up directly in the pending rows
let lines = d.lines || [];
if (!lines.length) {
  const g = String(d.group || '');
  lines = $('Find Pending Lines').all()
    .map(i => i.json)
    .filter(r => String(r.res_id || '') === g || String(r.res_id || '').startsWith(g + '-'));
}

// 2) still nothing -> show why, instead of returning no output
if (!lines.length) {
  return [{ json: { debug: 'no matching lines', group: d.group, action: d.action, ok: d.ok, toast: d.toast } }];
}

const approved = d.action === 'approve';
const exp = d.exp || $now.setZone('Africa/Cairo').plus({ hours: 2 }).toFormat('yyyy-MM-dd HH:mm');

return lines.map(l => ({
  json: {
    res_id: l.res_id,
    status: approved ? 'reserved' : 'rejected',
    expires_at: approved ? exp : '',
    pharmacist: d.by,
  },
}));

const d = $('Apply Decision').first().json;

// only change stock for an approved request that passed the checks
if (!d.ok || d.action !== 'approve') return [];

// total quantity reserved per SKU
const qty = {};
for (const l of d.lines) qty[l.sku] = (qty[l.sku] || 0) + Number(l.qty);

// current stock minus reserved quantity -> new stock per SKU
return d.newStock.map(s => ({
  json: { sku: s.sku, stock: s.stock - (qty[s.sku] || 0) },
}));
